@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500&display=swap');

:root {
  --dark-primary: #0F0F0F;
  --dark-secondary: #1a1a2e;
  --dark-tertiary: #16213e;
  --accent-blue: #2962FF;
  --accent-blue-hover: #3d73ff;
  --negative: #F7525F;
  --positive: #00C853;
  --text-primary: #ffffff;
  --text-secondary: #a0a0a0;
  --text-muted: #6b7280;
  --border: #2a2a3e;
  --card-bg: #1a1a2e;
  --card-hover: #222240;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  font-family: 'DM Sans', sans-serif;
  background: var(--dark-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
}

/* Utility Classes */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }
.text-2xl { font-size: 1.5rem; }
.text-3xl { font-size: 1.875rem; }
.text-4xl { font-size: 2.25rem; }

.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

.text-positive { color: var(--positive); }
.text-negative { color: var(--negative); }
.text-secondary { color: var(--text-secondary); }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--accent-blue); }

.mono { font-family: 'DM Mono', monospace; }

/* Navigation */
.nav {
  background: var(--dark-secondary);
  border-bottom: 1px solid var(--border);
  padding: 0 20px;
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo span {
  color: var(--accent-blue);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
  transition: color 0.2s;
  position: relative;
}

.nav-link:hover, .nav-link.active {
  color: var(--text-primary);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-content {
  position: absolute;
  top: 100%;
  left: 0;
  background: var(--dark-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 0;
  min-width: 180px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.2s;
}

.nav-dropdown:hover .nav-dropdown-content {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-item {
  display: block;
  padding: 8px 16px;
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.875rem;
  transition: all 0.2s;
}

.nav-dropdown-item:hover {
  background: var(--card-hover);
  color: var(--text-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}

.btn-primary:hover {
  background: var(--accent-blue-hover);
}

.btn-secondary {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  border-color: var(--text-secondary);
  color: var(--text-primary);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
}

.btn-ghost:hover {
  color: var(--text-primary);
}

.btn-sm {
  padding: 6px 12px;
  font-size: 0.8rem;
}

.btn-xs {
  padding: 4px 8px;
  font-size: 0.75rem;
}

/* Cards */
.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
}

.badge-positive {
  background: rgba(0, 200, 83, 0.15);
  color: var(--positive);
}

.badge-negative {
  background: rgba(247, 82, 95, 0.15);
  color: var(--negative);
}

.badge-neutral {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-secondary);
}

.badge-platinum {
  background: linear-gradient(135deg, #e2e2e2 0%, #b8b8b8 50%, #e2e2e2 100%);
  color: #1a1a1a;
}

.badge-gold {
  background: linear-gradient(135deg, #ffd700 0%, #ffaa00 50%, #ffd700 100%);
  color: #1a1a1a;
}

.badge-blue {
  background: rgba(41, 98, 255, 0.15);
  color: var(--accent-blue);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--dark-secondary);
  padding: 4px;
  border-radius: 8px;
}

.tab {
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  background: transparent;
}

.tab:hover {
  color: var(--text-primary);
}

.tab.active {
  background: var(--accent-blue);
  color: white;
}

/* Tables */
.table-container {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th, td {
  padding: 12px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

th {
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

tr:hover {
  background: var(--card-hover);
}

/* Stats Grid */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.stat-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
}

.stat-label {
  color: var(--text-secondary);
  font-size: 0.8rem;
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.25rem;
  font-weight: 600;
  font-family: 'DM Mono', monospace;
}

.stat-change {
  font-size: 0.8rem;
  font-family: 'DM Mono', monospace;
}

/* Market Ticker */
.ticker-container {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding: 12px 0;
}

.ticker-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 120px;
}

.ticker-name {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.ticker-price {
  font-family: 'DM Mono', monospace;
  font-weight: 600;
  font-size: 0.95rem;
}

.ticker-change {
  font-family: 'DM Mono', monospace;
  font-size: 0.8rem;
}

/* Section */
.section {
  padding: 40px 0;
}

.section-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 20px;
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.grid-6 {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

/* Footer */
.footer {
  background: var(--dark-secondary);
  border-top: 1px solid var(--border);
  padding: 60px 0 30px;
  margin-top: auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
}

.footer-title {
  color: var(--text-secondary);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 16px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.875rem;
  transition: color 0.2s;
}

.footer-link:hover {
  color: var(--text-primary);
}

.footer-bottom {
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-muted);
  font-size: 0.8rem;
}

/* Hero Section */
.hero {
  padding: 80px 0;
  text-align: center;
  background: linear-gradient(180deg, var(--dark-tertiary) 0%, var(--dark-primary) 100%);
}

.hero-badge {
  display: inline-block;
  padding: 6px 12px;
  background: rgba(41, 98, 255, 0.2);
  color: var(--accent-blue);
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 20px;
}

.hero-title {
  font-size: 3rem;
  font-weight: 700;
  margin-bottom: 16px;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.1;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
}

.hero-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
}

/* Sparkline placeholder */
.sparkline {
  width: 80px;
  height: 30px;
  display: inline-block;
}

/* Watchlist */
.watchlist-category {
  border-bottom: 1px solid var(--border);
}

.watchlist-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  cursor: pointer;
  transition: background 0.2s;
}

.watchlist-header:hover {
  background: var(--card-hover);
}

.watchlist-category-name {
  font-weight: 600;
  font-size: 0.875rem;
}

.watchlist-items {
  padding: 0 16px 12px;
}

.watchlist-item {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
  padding: 8px 0;
  font-size: 0.85rem;
}

.watchlist-symbol {
  font-weight: 600;
  font-family: 'DM Mono', monospace;
}

.watchlist-price {
  text-align: right;
  font-family: 'DM Mono', monospace;
}

.watchlist-change {
  text-align: right;
  font-family: 'DM Mono', monospace;
}

/* Chart Area */
.chart-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--dark-secondary);
  border-bottom: 1px solid var(--border);
}

.chart-timeframes {
  display: flex;
  gap: 4px;
}

.chart-timeframe {
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  transition: all 0.2s;
}

.chart-timeframe:hover {
  color: var(--text-primary);
}

.chart-timeframe.active {
  background: var(--accent-blue);
  color: white;
}

.chart-canvas {
  background: var(--dark-primary);
  padding: 20px;
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

/* Stock Detail Panel */
.stock-header {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 20px;
}

.stock-ticker {
  font-size: 1.5rem;
  font-weight: 700;
}

.stock-name {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.stock-exchange {
  color: var(--text-muted);
  font-size: 0.8rem;
}

.stock-price {
  font-size: 2rem;
  font-weight: 700;
  font-family: 'DM Mono', monospace;
}

.stock-change {
  font-family: 'DM Mono', monospace;
  font-size: 1rem;
}

/* Idea Cards */
.idea-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 16px;
}

.idea-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.idea-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.8rem;
}

.idea-meta {
  flex: 1;
}

.idea-author {
  font-weight: 600;
  font-size: 0.9rem;
}

.idea-time {
  color: var(--text-muted);
  font-size: 0.8rem;
}

.idea-type {
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
}

.idea-type.bullish {
  background: rgba(0, 200, 83, 0.15);
  color: var(--positive);
}

.idea-type.bearish {
  background: rgba(247, 82, 95, 0.15);
  color: var(--negative);
}

.idea-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.idea-symbol {
  display: inline-block;
  background: var(--dark-tertiary);
  padding: 2px 8px;
  border-radius: 4px;
  font-family: 'DM Mono', monospace;
  font-size: 0.8rem;
  margin-left: 8px;
}

.idea-description {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 16px;
}

.idea-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  color: var(--text-muted);
  font-size: 0.8rem;
}

.idea-stat {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Broker Cards */
.broker-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 16px;
}

.broker-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}

.broker-name {
  font-size: 1.25rem;
  font-weight: 600;
}

.broker-tier {
  margin-top: 4px;
}

.broker-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 16px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}

.broker-stat {
  text-align: center;
}

.broker-stat-value {
  font-size: 1.25rem;
  font-weight: 600;
  font-family: 'DM Mono', monospace;
}

.broker-stat-label {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.broker-promotion {
  color: var(--accent-blue);
  font-size: 0.9rem;
  font-weight: 500;
}

.broker-rating {
  display: flex;
  align-items: center;
  gap: 8px;
}

.broker-rating-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--positive);
}

.broker-rating-label {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Stats Banner */
.stats-banner {
  background: linear-gradient(135deg, var(--dark-tertiary) 0%, var(--dark-secondary) 100%);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 40px;
  text-align: center;
}

.stats-banner-value {
  font-size: 3rem;
  font-weight: 700;
  color: var(--accent-blue);
  margin-bottom: 8px;
}

.stats-banner-label {
  color: var(--text-secondary);
  font-size: 1rem;
}

/* Bond Table */
.bond-yield-bar {
  height: 4px;
  background: var(--dark-tertiary);
  border-radius: 2px;
  margin-top: 8px;
  overflow: hidden;
}

.bond-yield-fill {
  height: 100%;
  background: var(--accent-blue);
  border-radius: 2px;
}

/* Accordion */
.accordion {
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-trigger {
  width: 100%;
  padding: 16px;
  background: var(--card-bg);
  border: none;
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background 0.2s;
}

.accordion-trigger:hover {
  background: var(--card-hover);
}

.accordion-content {
  padding: 0 16px 16px;
  display: none;
}

.accordion-content.open {
  display: block;
}

/* Market Summary Bar */
.market-summary-bar {
  background: var(--dark-secondary);
  padding: 12px 0;
  overflow-x: auto;
}

.market-summary-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-right: 1px solid var(--border);
}

.market-summary-item:last-child {
  border-right: none;
}

.market-summary-name {
  color: var(--text-secondary);
  font-size: 0.8rem;
}

.market-summary-price {
  font-family: 'DM Mono', monospace;
  font-weight: 600;
  font-size: 0.9rem;
}

.market-summary-change {
  font-family: 'DM Mono', monospace;
  font-size: 0.8rem;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--dark-primary);
}

::-webkit-scrollbar-thumb {
  background: var(--dark-tertiary);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--border);
}

/* Responsive */
@media (max-width: 1200px) {
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4, .grid-6 {
    grid-template-columns: 1fr;
  }
  .hero-title { font-size: 2rem; }
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .broker-stats { grid-template-columns: 1fr; }
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-fadeIn {
  animation: fadeIn 0.4s ease-out forwards;
}

/* Chart Candlestick SVG */
.candlestick-chart {
  width: 100%;
  height: 300px;
}

/* Grain overlay */
.grain::before {
  content: '';
  position: fixed;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  opacity: 0.02;
  pointer-events: none;
  z-index: 1000;
}

